import{_ as a,o as t,c as o,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Coronation Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/25-coronation-profile.md","filePath":"reference/25-coronation-profile.md","lastUpdated":1788532705000}'),r={name:"reference/25-coronation-profile.md"};function n(s,e,h,l,c,d){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="coronation-source-profile" tabindex="-1">Coronation Source Profile <a class="header-anchor" href="#coronation-source-profile" aria-label="Permalink to &quot;Coronation Source Profile&quot;">​</a></h1><h2 id="claim-and-authority" tabindex="-1">Claim and authority <a class="header-anchor" href="#claim-and-authority" aria-label="Permalink to &quot;Claim and authority&quot;">​</a></h2><p>The <code>coronation</code> activity is linked to <code>muhurta.coronation</code>. Its authority is B. V. Raman&#39;s <em>Muhurtha</em>, Chapter XVI, &quot;Electing Head of the State&quot; and &quot;Coronation,&quot; printed page 66 (PDF page 70 in the registered edition). Raman is a modern secondary authority, not scripture.</p><p>The coronation paragraph says the immediately preceding head-of-state rules apply. The profile therefore admits the passage&#39;s twelve Nakshatras, its specified Tithis, and its eight rising Rasis. The text admits odd Shukla Tithis except Navami, plus Dwitiya and Dashami; the latter two are represented in both Pakshas because the passage does not qualify them by Paksha.</p><h2 id="chart-level-conditions" tabindex="-1">Chart-level conditions <a class="header-anchor" href="#chart-level-conditions" aria-label="Permalink to &quot;Chart-level conditions&quot;">​</a></h2><p>The source also requires strength for Surya, Chandra, Lagna, the 10th house and their lords, with a vacant 8th and malefics confined to Upachayas. These remain disclosed manual checks because the finder does not evaluate all of those chart relationships.</p><p>Raman then distinguishes two preferred configurations: Simha rising with Surya there and Guru&#39;s aspect for a traditional coronation; or a Kumbha-rising Shani configuration for the beginning of democratic rule. They are alternatives, not universal hard gates, and remain manual checks.</p><h2 id="deliberate-limits" tabindex="-1">Deliberate limits <a class="header-anchor" href="#deliberate-limits" aria-label="Permalink to &quot;Deliberate limits&quot;">​</a></h2><p>The existing samskara exclusions and Urdhva-Mukha score are separate project rules. This source claim does not lend them textual authority. Python and MCP publish the exact automated constraints and stable claim ID.</p>',9)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
